const PI_SOURCES = JSON.parse(PI_SOURCE_BYTES.toString("utf8")) as Record<string, { sha256: string; source: string }>;
export function reviewedPiSource(path: string): string {
	const entry = PI_SOURCES[path];
	assert.ok(entry, `Missing exact Pi 0.85.1 source fixture: ${path}`);
	assert.equal(createHash("sha256").update(entry.source).digest("hex"), entry.sha256, path);
	return entry.source;
}
